<script setup lang="ts">
import RecordPagination from '../components/RecordPagination.vue'
import BundleReleaseForm from '../components/workbench/BundleReleaseForm.vue'
const bundleReleaseId=ref('')
const releaseSize = ref(20)
import {computed,onMounted,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {getFlow,updateFlow} from '../api/flows'
import {activeFlow} from '../flow-session'
import {workflowContext} from '../workflow-context'
import {ElMessageBox,ElMessage} from 'element-plus'
import * as api from '../api/delivery'
import type {Release,Releases} from '../api/delivery'
import * as training from '../api/training'
import type {Model} from '../api/training'
import {organizations} from '../api/workbench'
import {session} from '../session'
const route=useRoute(),router=useRouter(),admin=computed(()=>session.user?.role==='ADMIN'),data=ref<Releases>(),page=ref(1),error=ref(''),busy=ref(false),departments=ref<Array<{organizationId:string;name:string}>>([]),predictionResult=ref<api.ReleasedResult>()
const prediction=reactive({organizationId:'',sentence1:'',sentence2:''})
const activeTab=ref(admin.value&&route.query.modelId?'new':'current')
const historyPage=ref(1),historySize=ref(20),historyTotal=ref(0),historyRows=ref<Releases['history']>([])
async function loadHistory(){try{const result=await api.releaseHistory(historyPage.value,historySize.value);historyRows.value=result.items;historyTotal.value=result.total}catch(v){error.value=v instanceof Error?v.message:'读取切换历史失败'}}
watch(activeTab,tab=>{if(tab==='history')void loadHistory()})
let timer:ReturnType<typeof setInterval>|undefined,alive=true,refreshing=false
async function load(){if(refreshing)return;refreshing=true;try{const value=await api.releases(page.value,releaseSize.value);if(route.query.release&&!value.items.some(r=>r.id===route.query.release))value.items.unshift(await api.release(String(route.query.release)));if(alive){data.value=value;if(activeFlow.value?.context.releaseId&&workflowContext.dataset){const released=value.items.find(r=>r.id===activeFlow.value!.context.releaseId);if(released)workflowContext.dataset={...workflowContext.dataset,modelReleases:[...(workflowContext.dataset.modelReleases||[]).filter(r=>r.id!==released.id),{id:released.id,versionId:activeFlow.value.context.versionId||'',status:released.status,active:value.pointers.some(p=>p.releaseId===released.id)}]}}}}catch(v){error.value=v instanceof Error?v.message:'读取版本失败'}finally{refreshing=false}}
async function perform(task:()=>Promise<void>){busy.value=true;error.value='';try{await task()}catch(v){error.value=v instanceof Error?v.message:'操作未完成'}finally{busy.value=false}}
function expected(row:Release){return data.value?.pointers.find(p=>p.scopeKey===`${row.organizationId}:${row.scene}`)?.releaseId??''}
async function switchVersion(row:Release){try{await ElMessageBox.confirm(`将${row.department}的${api.sceneNames[row.scene]}切换为“${row.name}”？`,'发布 / 回退',{confirmButtonText:'确认切换',cancelButtonText:'取消'})}catch{return}await perform(async()=>{await api.activate(row.id,expected(row));ElMessage.success('活动版本已切换');await load()})}
async function removeOverride(row:Release){try{await ElMessageBox.confirm('确认撤销该场景的专用版本，恢复默认选择？','恢复默认',{confirmButtonText:'恢复默认',cancelButtonText:'取消'})}catch{return}await perform(async()=>{await api.reset(row.organizationId,row.scene,expected(row));await load()})}
async function predict(){await perform(async()=>{if(!prediction.organizationId||!prediction.sentence1.trim()||!prediction.sentence2.trim())throw new Error('请选择部门并填写两段文本');predictionResult.value=await api.releasedPredict(prediction.organizationId,[{sentence1:prediction.sentence1,sentence2:prediction.sentence2}])})}
const releaseName=(id:string|null)=>id?data.value?.items.find(r=>r.id===id)?.name??id.slice(0,8):'默认选择'
async function registeredBundle(id:string){if(route.query.flow){const flow=await getFlow(String(route.query.flow));if(flow.context.bundleId===bundleReleaseId.value)activeFlow.value=await updateFlow(flow,{...flow.context,releaseId:id},'predict')}activeTab.value='current';page.value=1;ElMessage.success('已提交整组核验');await router.replace({query:{...route.query,release:id,tab:'current'}});await load()}
async function restoreRoute(){bundleReleaseId.value=String(route.query.bundleId||'');if(route.query.modelId&&!bundleReleaseId.value){const model=await training.model(String(route.query.modelId));bundleReleaseId.value=(model as Model&{bundleId?:string}).bundleId||''}if(admin.value&&bundleReleaseId.value&&route.query.tab!=='current')activeTab.value='new'}
watch(()=>[route.query.bundleId,route.query.modelId,route.query.tab],()=>void perform(restoreRoute))
onMounted(()=>{void perform(async()=>{const orgs=await organizations();departments.value=orgs;prediction.organizationId=orgs[0]?.organizationId??'';await restoreRoute();await load()});timer=setInterval(()=>void load(),3000)});onBeforeUnmount(()=>{alive=false;if(timer)clearInterval(timer)})
</script>
<template><div class="page-toolbar"><p class="muted">按部门和使用场景管理生效版本，保留每次切换记录。</p></div><el-tabs v-model="activeTab" class="workspace-tabs"><el-tab-pane label="当前版本与切换" name="current"/><el-tab-pane v-if="admin" label="登记发布" name="new"/><el-tab-pane label="试用已发布模型" name="try"/><el-tab-pane label="切换历史" name="history"/></el-tabs><el-alert v-if="error" :title="error" type="error" :closable="false"/><section v-show="activeTab==='current'" class="panel"><div class="section-heading"><h2>当前生效版本</h2><el-button @click="load">刷新</el-button></div><div class="release-pointers"><div v-for="p in data?.pointers.filter(p=>p.releaseId)" :key="p.scopeKey"><span>{{p.scopeKey.startsWith('0:')?'校级默认':departments.find(d=>d.organizationId===p.scopeKey.split(':')[0])?.name}} · {{api.sceneNames[p.scopeKey.split(':')[1]!]}}</span><strong>{{releaseName(p.releaseId)}}</strong></div></div><el-empty v-if="!data?.pointers.some(p=>p.releaseId)" description="当前沿用默认审核配置，可登记版本后发布" :image-size="60"/></section>
<BundleReleaseForm v-if="admin&&activeTab==='new'" :bundle-id="bundleReleaseId" @registered="registeredBundle"/>
<section v-show="activeTab==='current'" class="panel"><h2>发布版本与回退</h2><el-table :data="data?.items ?? []" empty-text="暂无发布版本"><el-table-column prop="name" label="版本" min-width="180"/><el-table-column prop="department" label="范围" min-width="140"/><el-table-column label="场景" width="120"><template #default="{row}">{{api.sceneNames[row.scene]}}</template></el-table-column><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="expected(row)===row.id?'success':row.status==='FAILED'?'danger':'info'">{{expected(row)===row.id?'使用中':api.deliveryStates[row.status]}}</el-tag></template></el-table-column><el-table-column label="核验与评价" min-width="220"><template #default="{row}"><span v-if="row.error" class="unsaved">{{row.error}}</span><span v-else-if="row.manifest?.bundleId">六模型已核验 · 主模型 {{row.manifest.primaryFamily?.toUpperCase()}}<details><summary>逐模型评价</summary><p v-for="member in row.manifest.members" :key="member.modelId">{{member.family.toUpperCase()}} · 验证 Macro-F1 {{(member.calibration.macroF1*100).toFixed(1)}}% · 验证误报 {{(member.calibration.falsePositiveRate*100).toFixed(1)}}% · 测试 F1 {{(member.calibratedTest.f1*100).toFixed(1)}}%</p></details></span><span v-else-if="row.manifest?.development">改写来源检出 {{row.manifest.development.candidate.known.completeCorrectSourceDocuments}}/{{row.manifest.development.candidate.known.positiveDocuments}} · 正常对照提示 {{row.manifest.development.candidate.known.scopedNormalAlerts}}/{{row.manifest.development.candidate.known.normalDocuments}}<br/>真实新闻提示 {{row.manifest.development.candidate.realNewsAlertedDocuments}}/{{row.manifest.development.realNewsCases}} · 校准阈值 {{row.manifest.calibration?.threshold.toFixed(4)}}</span><span v-else-if="row.manifest?.metrics">Macro-F1 {{(row.manifest.metrics.macro_f1*100).toFixed(2)}}% · 阈值 {{row.manifest.threshold}}</span><span v-else>{{row.manifest?.textConfig?.method || '等待核验'}}<template v-if="row.manifest?.profileId"> · 参考库 {{row.manifest.libraryGenerationId}}</template></span></template></el-table-column><el-table-column v-if="admin" label="操作" width="200"><template #default="{row}"><el-button size="small" :disabled="busy||row.status!=='READY'||expected(row)===row.id" @click="switchVersion(row)">发布 / 回退</el-button><el-button v-if="expected(row)===row.id" size="small" :disabled="busy" @click="removeOverride(row)">恢复默认</el-button></template></el-table-column></el-table><RecordPagination v-model:current-page="page" v-model:page-size="releaseSize" :total="data?.total??0" @change="load" /></section>
<section v-show="activeTab==='try'" class="panel"><h2>使用已发布模型组预测</h2><el-form label-position="top"><el-form-item label="使用部门"><el-select v-model="prediction.organizationId"><el-option v-for="d in departments" :key="d.organizationId" :value="d.organizationId" :label="d.name"/></el-select></el-form-item><div class="prediction-pair"><el-form-item label="原文"><el-input v-model="prediction.sentence1" type="textarea" :rows="3"/></el-form-item><el-form-item label="待比对文本"><el-input v-model="prediction.sentence2" type="textarea" :rows="3"/></el-form-item></div></el-form><el-button type="primary" :loading="busy" @click="predict">按活动版本预测</el-button><div v-if="predictionResult?.bundleResults" class="work-stats"><div v-for="member in predictionResult.bundleResults" :key="member.modelId"><span>{{member.family.toUpperCase()}}<template v-if="member.family===predictionResult.primaryFamily"> · 主模型</template></span><strong>{{member.rows[0]?.predicted===1?'语义相近':'语义不同'}}</strong><small>支持度 {{((member.rows[0]?.score||0)*100).toFixed(1)}}%</small></div></div><div v-if="predictionResult" class="release-pointers"><div><span>发布版本 {{predictionResult.releaseId.slice(0,8)}}</span><strong>{{predictionResult.rows[0]?.predicted===1?'语义相近':'语义不同'}}</strong></div><div><span>{{predictionResult.rows[0]?.scoreType==='margin'?'间隔分数':'模型分数'}}</span><strong>{{predictionResult.rows[0]?.score.toFixed(4)}}</strong></div></div></section>
<section v-show="activeTab==='history'" class="panel"><h2>切换记录</h2><el-table :data="historyRows" empty-text="暂无切换记录"><el-table-column label="范围 / 场景" min-width="190"><template #default="{row}">{{row.scopeKey}}</template></el-table-column><el-table-column label="原版本" min-width="180"><template #default="{row}">{{releaseName(row.previousId)}}</template></el-table-column><el-table-column label="切换至" min-width="180"><template #default="{row}">{{releaseName(row.releaseId)}}</template></el-table-column><el-table-column label="时间" min-width="180"><template #default="{row}">{{new Date(row.createdAt).toLocaleString('zh-CN')}}</template></el-table-column></el-table><RecordPagination v-model:current-page="historyPage" v-model:page-size="historySize" :total="historyTotal" @change="loadHistory" /></section></template>
<style scoped>.release-form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.release-form .el-select{width:100%}.release-pointers{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.release-pointers>div{border:1px solid var(--line);padding:20px;background:color-mix(in srgb,var(--el-color-primary) 6%,var(--canvas))}.release-pointers span{display:block;color:var(--muted);font-size:12px}.release-pointers strong{display:block;font-size:23px;margin-top:12px}.prediction-pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}.link-gap{margin-left:18px}@media(max-width:1000px){.release-form{grid-template-columns:1fr 1fr}}@media(max-width:700px){.release-form,.release-pointers,.prediction-pair{grid-template-columns:1fr}}</style>
